<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {CompanyConnectionsClient,CompanyConnectionError,type ConnectionRequest,type CredentialSchema} from './company-connections-client';import CompanyCredentialForm from './CompanyCredentialForm.svelte';import './automations.css';
 export let companyId:string;export let actorId:string;export let conversationId:string;export let requestId:string;export let credentialType:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher<{close:void;denied:{status:number}}>();let mounted=false,key='',watched:AbortSignal|undefined,client:CompanyConnectionsClient|undefined,request:ConnectionRequest|null=null,schema:CredentialSchema|null=null,generation=0,busy=false,error='',session='',formReset=0;
 $: if(mounted&&(key!==[companyId,actorId,conversationId,requestId,credentialType].join('\0')||watched!==accessSignal)){reset();key=[companyId,actorId,conversationId,requestId,credentialType].join('\0');watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{session=localStorage.getItem('token')||'';client=new CompanyConnectionsClient(companyId,conversationId,requestId,credentialType,()=>localStorage.getItem('token')||'',watched);void load();}}
 function reset(){generation++;client?.close();client=undefined;watched?.removeEventListener('abort',lost);request=null;schema=null;busy=false;error='';formReset++;}
 function lost(){reset();dispatch('close');}
 function fail(e:unknown){if(e instanceof CompanyConnectionError&&(e.status===401||e.status===403)){lost();dispatch('denied',{status:e.status});return;}error=e instanceof Error?e.message:'The company connection could not be checked.';}
 async function load(){if(!client||busy)return;const c=client,n=generation;busy=true;error='';formReset++;schema=null;try{const next=await c.get();if(n!==generation)return;request=next;if(next.status==='REQUESTED'){const fields=await c.schema();if(n===generation)schema=fields;}}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 async function submit(payload:{displayName:string;data:Record<string,unknown>}){if(!client||!request||!schema||busy)return;const c=client,n=generation;busy=true;error='';formReset++;try{const next=await c.submit(request,schema,payload.displayName,payload.data);if(n!==generation)return;request=next;schema=null;}catch(e){if(n===generation){schema=null;request=null;fail(e);}}finally{for(const k of Object.keys(payload.data))delete payload.data[k];if(n===generation)busy=false;}}
 async function reuseSlack(){if(!client||!request||busy)return;const c=client,n=generation;busy=true;error='';try{const next=await c.reuseSlack(request);if(n===generation){request=next;schema=null;}}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 function storage(e:StorageEvent){if(e.key===null||e.key==='token')lost();}
 onMount(()=>{mounted=true;window.addEventListener('storage',storage);const timer=setInterval(()=>{if(client&&session!==(localStorage.getItem('token')||''))lost();},500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('storage',storage);});
</script>
<section class="starli-automations connection-card" aria-label="Company connection setup"><span class="sa-eyebrow">COMPANY CONNECTION</span><h3>Set up a company account</h3><p class="sa-muted">Use this protected form to provide the official connection fields. Credentials stay out of chat.</p>
{#if error}<p class="sa-error" role="alert">{error}</p>{/if}
{#if request?.status==='REQUESTED'&&request.canReuseConnectedSlack}<button class="sa-primary" disabled={busy} on:click={()=>void reuseSlack()}>Use connected company Slack</button><p class="sa-muted">Reuse your company’s existing Slack authorization without entering a token.</p>{/if}
{#if request?.status==='STORED_NOT_VERIFIED'}<h4>Stored · not verified</h4><p>{request.displayName}</p><p class="sa-muted">The credential is stored for this company. Account verification and permission to execute connector actions are still required.</p>
{:else if request?.status==='UNCERTAIN'}<p role="status">The save outcome is uncertain. Refresh the saved status; do not submit the credential again.</p>
{:else if request?.status==='NEEDS_PLATFORM_APP'}<p role="status">Secure OAuth consent needs Starli’s platform app configuration. No account connection has been confirmed.</p>
{:else if schema}{#key generation+':'+formReset}<CompanyCredentialForm {schema} {busy} resetKey={String(formReset)} on:submit={e=>void submit(e.detail)}/>{/key}
{:else if busy}<p role="status">Checking the saved company request…</p>{/if}
<button disabled={busy} on:click={()=>void load()}>Refresh status</button></section>
<style>.connection-card{max-width:740px;padding:20px;margin:12px 0;background:#fafbfd;border:1px solid #e6ebf4;border-radius:12px}.connection-card h3{margin:8px 0}.connection-card>button{margin-top:16px}@media(max-width:500px){.connection-card{padding:15px;min-width:0;max-width:100%}}</style>
